  // v2.3（§7.2/§7.3）：模式短标签 + 步骤进度文案 + 记忆开关\n  modeShortBase: '基础',\n  modeShortLite: '轻量',\n  modeShortStandard: '标准',\n  modeShortSmart: '专家',\n  modeShortPublish: '发布',\n  // v3.1.7（用户反馈·设置页模式下拉不跟随语言）：模式全称（设置页「优化模式」下拉选项）\n  modeLabelBase: '基础模式',\n  modeLabelLite: '轻量模式',\n  modeLabelStandard: '标准模式',\n  modeLabelSmart: '专家模式',\n  modeLabelPublish: '一键发布',\n  // v3.0r（细粒度进度反馈）：子步骤详情文案（detailKey → 模板，{current}/{total}/{query} 占位）\n  // 2026-08-18（用户需求）：按钮提醒精简——4~6 字，保留进度数字（{current}/{total}），去 query\n  stagePrepare: '正在准备',\n  stageHistory: '读取会话',\n  stageAnalyze: '分析任务',\n  stageFiles: '检索文件',\n  stageEvents: '检索会话',\n  stageContext: '组装上下文',\n  stageLlm: '模型调用中',\n  stageDetailJudge: '判定 {current}/{total}',\n  stageDetailIntent: '判定意向',\n  stageDetailDocs: '分析文档',\n  stageDetailCode: '检索代码',\n  stageDetailPlan: '规划检索',\n  stageDetailSearch: '搜索 {current}/{total}',\n  stageDetailScan: '扫描工作区',\n  stageDetailRetry: '重试 {current}/{total}',\n  stageDetailProbe: '连通 {current}/{total}',\n  stageDone: '✓',\n};\n\nconst EN = {\n  enhanceButton: 'Optimize',\n  enhancing: 'Optimizing',\n  // 2026-08-18（用户需求）：llm 阶段显示正在优化的模型序号；重试精简\n  enhancingModel: '{n} optimizing',\n  result: 'Undo',\n  resultFallback: 'Undo',\n  titleIdle: 'Optimize prompt',\n  // v2.6.2（继续优化）：已优化过一轮后修改草稿的按钮文字与提示\n  btnContinue: 'Continue',\n  titleContinue: 'Continue optimizing',\n  titleBusy: 'Click to cancel',\n  titleResult: 'Click to undo',\n  titleCommand: 'Nothing to optimize',\n  titleBusyInput: 'Not ready',\n  // v3.5.3 (split button): disabled main-key hint for empty input (the two old empty-click memory-toggle hints retired with it)\n  titleEmptyInput: 'Type something to optimize',\n  // v3.5.3 (▾ menu): trigger + section headers (on/off reuse cfgReasoningOn/Off; empty states reuse cfgNoProvider/cfgLoadFailed)\n  menuTrigger: 'Enhancement settings',\n  menuMemory: 'Memory chain',\n  menuModels: 'Model',\n  menuEffort: 'Effort',\n  menuMode: 'Mode',\n  menuBack: 'Back',\n  menuEffortUnsupported: 'No reasoning',\n  errorPrefix: 'Optimize failed: ',\n  dismiss: 'Dismiss',\n  cancel: 'Cancel',\n  errGUARD: 'Empty input or slash command is not supported',\n  errNO_LLM: 'LLM service unavailable',\n  // 2026-08-18（用户需求·删内置兜底链）：未配置模型时明确提示\n  errNO_MODEL: 'No model selected — pick one in settings first',\n  errUNKNOWN_MODEL: 'Optimize model unavailable (not in the catalog)',\n  errNO_ADAPTER: 'LLM provider not enabled',\n  errINVALID_CREDENTIAL: 'Invalid or missing API key',\n  errQUOTA: 'Model quota exceeded',\n  errCONTEXT_WINDOW_EXCEEDED: 'Input exceeds the context window',\n  errEMPTY_RESPONSE: 'Model returned an empty response',\n  errOUTPUT_TOO_LONG: 'Optimization exceeds the length limit',\n  errTIMEOUT: 'Request timed out, original text restored',\n  errABORTED: 'Request cancelled',\n  errLLM_FAILED: 'Optimize failed, please retry',\n  errNETWORK: 'Network error',\n  errUNKNOWN: 'Optimize failed',\n  errAllModels: 'Model connection failed — check your model config (network, API key or model availability)',\n  errModelUnreachable: 'Model connection failed (network or config)',\n  pluginsEmpty: 'No plugins defined yet',\n  // 2026-08-18（用户需求）：插件管理板块项目地址跳转链接（版本检测与更新下方）\n  cfgProjectLink: 'Project: GitHub · HXHndj/dsh-prompt-enhancer ↗',\n  pluginsLoadFailed: 'Reading the plugin inventory failed',\n  pluginsRunning: 'Running',\n  pluginsStopped: 'Stopped',\n  pluginsDefined: 'Not running',\n  pluginsAwaiting: 'Awaiting approval',\n  pluginsFailed: 'Failed',\n  pluginsClientPending: 'Activating',\n  pluginsWaiting: 'Waiting for services',\n  pluginsVersion: 'Version',\n  pluginsCurrent: 'Current',\n  // v2.4.3：version switch confirmation\n  pluginsTarget: 'Target version',\n  pluginsSwitch: 'Confirm switch',\n  // v2.4.3-fix：incomplete package marker\n  pluginsIncomplete: ' (incomplete)',\n  pluginsRun: 'Run',\n  pluginsStop: 'Stop',\n  pluginsRemove: 'Remove',\n  pluginsDecline: 'Decline',\n  pluginsApproveOnce: 'Approve (this version only)',\n  pluginsActionFailed: 'Operation failed',\n  pluginsRefresh: 'Refresh',\n  // v2.4.0（方案 §4）：版本检测与更新卡片\n  updTitle: 'Version check & update',\n  // v2.7.0：更新未重启提醒\n  updRestartNeeded: '⚠️ Plugin files were updated but the service has not restarted — restart to activate the new version. Restart command: ',\n  updRepo: 'GitHub repo',\n  updCheck: 'Check version',\n  updChecking: 'Checking…',\n  updLocal: 'Local',\n  updRemote: 'Remote',\n  updOutdated: 'New version available',\n  updCurrent: 'Up to date',\n  updAhead: 'Local is ahead',\n  updUnknown: 'Unknown',\n  updDir: 'Target directory',\n  updPull: 'Update',\n  updPullApplyConfirm: 'Confirm update?',\n  // v3.3.x (user directive · plugin-side restart removed): one-click update = executor download+verify (staged) → host install → prompt the user to restart DSH manually\n  updStaged: '✓ Installed — restart DSH manually to activate the new version',\n  updStagedShort: 'Installed',\n  updError: 'Operation failed, please retry',\n  updRepoNotFound: 'Repository not found or unreachable (HTTP 404)',\n  // v2.5.0 (one-click update & restart + environment check)\n  envBtn: 'Check env',\n  envChecking: 'Checking…',\n  envTitle: 'Environment',\n  envOk: 'OK',\n  // v2.7.0（重启工具可用性检查）\n  envTools: 'Restart tools',\n  envToolsMissing: 'Missing restart commands (sc/netstat/reg) — check the system directory',\n  // v2.7.1（网络预检 + 工具不可达降级）\n  envNet: 'Network (GitHub)',\n  envNetUnreachable: 'GitHub unreachable — one-click update install may fail (check network/proxy)',\n  envToolUnreachable: 'System tools unreachable (PATH broken) — results unreliable, check the system environment',\n  // v3.2.1-o (env-check rework): port host mode and current PID (replaces exec-port)\n  envPortMode: 'Port host mode',\n  envPortModeService: 'Service mode (nssm, Session 0)',\n  envPortModeServiceStopped: 'Service mode, installed but not running',\n  envPortModeDefault: 'Foreground mode (user session)',\n  envPortModePidOnly: 'Process mode (session unknown)',\n  envPortModeDesktop: 'Desktop app (port managed by client)',\n  envUnsupportedPlatform: 'Unsupported platform — environment detection supports Windows/Linux only',\n  envPortModeNoListener: 'Not running (no port listener)',\n  envPortPid: 'Port PID',\n  updApplying: 'Installing update… (10–60s)',\n  updApplyStaging: 'Downloading update resources…',\n  updApplyEnvcheck: 'Checking environment…',\n  updApplyPreparing: 'Preparing install…',\n  updApplyRollingBack: 'Restart failed — rolling back to previous version…',\n  updApplyRolledBack: '✓ Rolled back to the previous version — refresh the page',\n  updApplyRestartFailed: 'Install failed — retry; if it still fails, restart the DSH service manually and refresh',\n  updDiagTitle: 'dsh-web error log tail (likely root cause, redacted)',\n  updApplyExecutorDown: 'Update failed: the update executor is unreachable or the install did not complete. Make sure the executor is running and retry',\n\n\n  // v2.9.x (install-without-restart fix): old executor lacks restart:false — block and ask to restart dsh web\n  updExecutorTooOld: 'Update executor is too old (v{v}) and does not support install-without-restart — restart dsh web to upgrade the executor (≥0.1.7), then retry',\n  updCheckFirst: 'Run \"Check version\" first to confirm a new version before updating',\n  updApplyBlocked: 'Environment check failed, resolve first: ',\n  cfgTimeout: 'Timeout',\n  cfgMaxTokens: 'Max output tokens',\n  cfgOutputLimit: 'Output character limit',\n  cfgTemplateMode: 'Template',\n  cfgTemplateText: 'Custom template text',\n  // v2.4.7（per-mode）：label 带当前模式名；hint 说明独立与回退语义\n  cfgTemplateTextFor: 'Custom template text (current mode: {mode})',\n  // Template system extension (2026-08-18 rev): 2 built-in templates per mode + multiple custom templates\n  tplDefault: 'Default template',\n  tplIncrement: 'Increment template',\n  tplCustom: 'Custom: {name}',\n  tplAddCustom: '+ New custom template',\n  tplRemoveCustom: 'Delete template',\n  tplName: 'Template name',\n  tplNamePlaceholder: 'Template name (≤40 chars)',\n  tplNote: 'Each mode picks built-in Default (restates only) or Increment (conservatively fills missing big logic); or a custom template (≤4000 chars).',\n  cfgSaved: '✓ Saved',\n  // v2.7.0：保存校验状态（转圈/失败）\n  cfgSaving: 'Saving…',\n  cfgSaveFailed: '✗ Save failed, please retry',\n  cfgLoadFailed: 'Failed to load models',\n  cfgNoProvider: 'No LLM provider configured',\n  cfgHint: 'Settings are stored locally (localStorage) and apply to this instance only.',\n  // v3.5.2 (hierarchical layout): text group headers for the four Optimization groups\n  cfgGroupBehavior: 'Optimization behavior',\n  cfgGroupContext: 'Memory & context',\n  cfgGroupRuntime: 'Runtime parameters',\n  cfgGroupTemplate: 'Custom templates',\n  cfgLogs: 'Diagnostics log',\n  cfgLogsEmpty: 'No logs yet (they appear after optimizations)',\n  navModelPlugins: 'Prompt Enhancer',\n  // 2026-08-16（方案「设置界面样式与交互对齐官方」）：设置页 section 简介\n  secPluginsIntro: 'Model, optimization parameters, and plugin management in one place; changes save immediately.',\n  tabModels: 'Models',\n  tabParams: 'Optimization',\n  tabPlugins: 'Plugins',\n  secMain: 'Model configuration',\n  // v3.6 (single-select): current-model summary / legacy queue convergence note\n  secSingleModel: 'Current model: {name}',\n  cfgLegacyMulti: 'Legacy multi-model queue detected ({n} models). This version uses a single model: the first one is in effect and the rest are kept for now; your next model change (including clearing it) will converge the config to the new selection.',\n  secFallbackEmpty: 'No model selected — pick one before optimizing',\n  cfgReasoningOn: 'On',\n  cfgReasoningOff: 'Off',\n  // 2026-08-18（用户需求）：模型行操作 hover 提示（思考开关/上移/下移/删除）\n  selThinking: 'Enable/disable model thinking',\n  cfgModelLabel: 'Current model',\n  cfgProviderLabel: 'Provider',\n  cfgModelNameLabel: 'Model',\n  cfgReasoningLabel: 'Thinking',\n  cfgEffortLabel: 'Effort',\n  rowRemove: 'Clear this